const viewports=[{width:1440,height:900},{width:1024,height:768},{width:820,height:1180},{width:390,height:844}]
async function navigate(page,name){await page.locator('.nav-button').filter({hasText:name}).filter({visible:true}).click();await page.waitForTimeout(170)}
async function verifyProfileLogo(page,selector='.brand-mascot svg'){
  assert.equal(await page.title(),'DiskCollie')
  assert.equal((await page.locator('.brand-version').innerText()).trim(),`v${expectedVersion}`,'UI smoke must use the current checkout version')
  assert.equal(await page.locator('.brand-copy>strong').innerText(),'DiskCollie')
  assert(await page.locator('.brand').evaluate(element=>element.scrollWidth<=element.clientWidth+1),'DiskCollie branding must fit at every viewport')
  const logo=page.locator(selector)
  assert.equal(await logo.getAttribute('data-mascot-view'),'profile','Branding must show the collie side profile');assert.equal(await logo.getAttribute('data-facing'),'left','The approved logo faces left')
  assert(await logo.isVisible(),'The profile logo must remain visible')
  assert(await logo.evaluate(svg=>{const box=svg.getBBox(),view=svg.viewBox.baseVal;return box.x>=view.x&&box.y>=view.y&&box.x+box.width<=view.x+view.width&&box.y+box.height<=view.y+view.height}),'The profile must fit its viewBox')
  assert(await logo.evaluate(svg=>getComputedStyle(svg).fill===getComputedStyle(svg.closest('.collie-mark')).color),'The logo must follow the selected theme')
}
async function privacyPreview(page,id){await page.locator(`.space-privacy [data-privacy-id="${id}"] .privacy-type-action`).click();const dialog=page.locator('.privacy-preview-dialog');await dialog.locator('.privacy-record-item').first().waitFor();return dialog}
async function verifyPrivacyAppSorting(page){
  const privacy=page.locator('.space-privacy')
  await privacy.locator('.privacy-categories button').filter({hasText:'应用活动'}).click()
  const source=key=>privacy.locator(`[data-privacy-source="${key}"]`)
  const order=()=>privacy.locator('.privacy-source').evaluateAll(items=>items.map(item=>item.dataset.privacySource))
  const name=privacy.locator('[data-privacy-sort="name"]'),count=privacy.locator('[data-privacy-sort="count"]'),code=source('vscode')
  await code.locator('img.privacy-source-logo').waitFor()
  assert.equal(await source('empty-app').count(),0,'Applications with a verified zero count must be hidden')
  assert.equal(await source('restricted-app').count(),1,'Unknown permission counts must stay visible')
  assert.equal(await source('restricted-app').locator('.privacy-source-heading>input').isEnabled(),false)
  assert.equal(await name.getAttribute('data-sort-direction'),'ascending')
  assert.deepEqual(await order(),['figma','restricted-app','vscode'])
  assert.equal(await code.locator('.privacy-profile').count(),2,'Profiles from one app must stay together')
  const selected=code.locator('[data-privacy-id="app-recent"] input')
  await selected.check()
  await name.click()
  assert.equal(await name.getAttribute('data-sort-direction'),'descending')
  assert.deepEqual(await order(),['vscode','restricted-app','figma'])
  assert(await selected.isChecked(),'Sorting must retain selected traces')
  await code.locator('.privacy-source-toggle').click()
  assert.equal(await code.locator('.privacy-source-toggle').getAttribute('aria-expanded'),'false')
  await count.click()
  assert.equal(await count.getAttribute('data-sort-direction'),'descending')
  assert.deepEqual(await order(),['vscode','figma','restricted-app'])
  assert.equal(await code.locator('.privacy-source-toggle').getAttribute('aria-expanded'),'false','Sorting must retain collapsed apps')
  await count.click()
  assert.equal(await count.getAttribute('data-sort-direction'),'ascending')
  assert.deepEqual(await order(),['figma','vscode','restricted-app'])
  await code.locator('.privacy-source-toggle').click()
  assert(await selected.isChecked())
  assert.deepEqual(await code.locator('.privacy-record-row').evaluateAll(items=>items.map(item=>item.dataset.privacyId)),['app-recent','app-logs','app-work-recent'])
  await navigate(page,'大文件');await navigate(page,'隐私清理')
  assert.equal(await count.getAttribute('data-sort-direction'),'ascending','Page switches must retain the app sort')
  assert(await selected.isChecked(),'Page switches must retain selected traces')
  assert.equal(await code.locator('.privacy-source-toggle').getAttribute('aria-expanded'),'true')
  await selected.uncheck()
  await name.click()
  assert.deepEqual(await order(),['figma','restricted-app','vscode'])
}
